package com.anssa8bu.ssafy.common.redis.service; import org.slf4j.*; import org.springframework.stereotype.Service; import org.springframework.transaction.support.*; import java.util.*; import java.util.function.*; @Service public class CacheAsideService {private static final Logger log=LoggerFactory.getLogger(CacheAsideService.class);public <T>T get(Supplier<Optional<T>> cache,Supplier<T> database,Consumer<T> populate){try{Optional<T> hit=cache.get();if(hit.isPresent())return hit.get();}catch(RuntimeException e){log.warn("Redis cache read failed; using database");}T value=database.get();try{populate.accept(value);}catch(RuntimeException e){log.warn("Redis cache populate failed");}return value;}public void invalidateAfterCommit(Runnable invalidation){if(TransactionSynchronizationManager.isActualTransactionActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){safe(invalidation);}});else safe(invalidation);}private void safe(Runnable r){try{r.run();}catch(RuntimeException e){log.warn("Redis cache invalidation failed");}}}
